                { "offset", offset },
                { "limit", reqLimit },
            };
            object response = await this.sapiPrivateGetMarketList(this.extend(request, rest));
            //
            //     {
            //         "marketTopics": [
            //             {
            //                 "marketTopicId": 4229564,
            //                 "vendor": "PREDICT_FUN",
            //                 "chainId": "56",
            //                 "slug": "btc-price-1h-up-or-down",
            //                 "title": "BTC Price 1h Up or Down?",
            //                 "question": "Will BTC price go UP?",
            //                 "topicType": "FLAT",
            //                 "chartType": "CRYPTO_UP_DOWN",
            //                 "symbol": "BTCUSDT",
            //                 "participantCount": 3420,
            //                 "collateral": "USDT",
            //                 "feeRateBps": 200,
            //                 "slippageBps": 1200,
            //                 "tradeVolume": "158234.56",
            //                 "liquidity": "45000.00",
            //                 "publishedAt": 1748100000000,
            //                 "startDate": 1748131200000,
            //                 "endDate": 1748134800000,
            //                 "status": "REGISTERED",
            //                 "markets": []
            //             }
            //         ],
            //         "total": 128,
            //         "offset": 0,
            //         "limit": 20,
            //         "hasMore": true
            //     }
            //
            object pageTopics = (IList<object>)(this.safeList(response, "marketTopics", new List<object>() {}));
            object pageTopicsLength = getArrayLength(pageTopics);
            for (object i = 0; isLessThan(i, pageTopicsLength); postFixIncrement(ref i))
            {
                ((IList<object>)collected).Add(getValue(pageTopics, i));
            }
            object hasMore = this.safeBool(response, "hasMore", false);
            if (isTrue(!isTrue(hasMore) || isTrue((isLessThan(pageTopicsLength, reqLimit)))))
            {
