    /**
     * @ignore
     * @method
     * @name binance#completeRawTopics
     * @description ensures each raw topic carries fully-populated nested markets (with outcome token ids), fetching the topic detail when the listing/search payload omitted them
     * @param {object[]} rawTopics raw market topic objects
     * @returns {object[]} raw market topic objects with usable nested markets
     */
    public async virtual Task<object> completeRawTopics(object rawTopics)
    {
        object result = new List<object>() {};
        object rawTopicsLength = getArrayLength(rawTopics);
        for (object i = 0; isLessThan(i, rawTopicsLength); postFixIncrement(ref i))
        {
            object rawTopic = getValue(rawTopics, i);
            object rawMarkets = (IList<object>)(this.safeList(rawTopic, "markets", new List<object>() {}));
            object rawMarketsLength = getArrayLength(rawMarkets);
            object hasOutcomes = false;
            if (isTrue(isGreaterThan(rawMarketsLength, 0)))
            {
                object firstMarket = this.safeDict(rawMarkets, 0, new Dictionary<string, object>() {});
                object firstOutcomes = (IList<object>)(this.safeList(firstMarket, "outcomes", new List<object>() {}));
                object firstOutcomesLength = getArrayLength(firstOutcomes);
                hasOutcomes = (isGreaterThan(firstOutcomesLength, 0));
            }
            if (isTrue(hasOutcomes))
            {
                ((IList<object>)result).Add(rawTopic);
            } else
            {
                object topicId = this.safeString(rawTopic, "marketTopicId");
                if (isTrue(!isEqual(topicId, null)))
                {
                    object detail = await this.fetchRawTopicDetail(topicId);
                    ((IList<object>)result).Add(detail);
                }
            }
        }
        return result;
    }

    /**
     * @method
     * @name binance#fetchEvents
     * @description fetches prediction-market events (market topics); the call must be scoped by query/queries/tags, eventId, or an l1Category/l2Category listing filter
     * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/market-data
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.query] a free-text search resolved against the semantic market search endpoint
     * @param {string[]} [params.queries] multiple free-text searches (alternative to query)
     * @param {string[]} [params.tags] treated as additional free-text searches (binance has no tag taxonomy)
     * @param {string} [params.eventId] a marketTopicId, fetched directly via the detail endpoint
     * @param {string} [params.l1Category] scope the listing server-side by a level-1 category id
     * @param {string} [params.l2Category] scope the listing server-side by a level-2 category id
     * @param {int} [params.limit] the maximum number of events to return
     * @param {string} [params.sort] 'volume' | 'liquidity' | 'newest' (client-side)
     * @param {string} [params.status] 'active' | 'closed' | 'all' (client-side)
     * @param {string} [params.sortBy] sort events by server side ('RECOMMENDED' | 'VOLUME' | 'PARTICIPANTS' | 'CREATED_TIME' | 'END_DATE'), works when no queries and eventId provided
     * @param {string} [params.orderBy] order events by server side ('ASC' | 'DESC'), works when no queries and eveitId provided
     * @returns {object[]} a list of [prediction event structures](https://docs.ccxt.com/#/?id=prediction-event-structure)
     */
    public async override Task<object> fetchEvents(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        object allowUnscopedFetchEvents = this.safeBool(this.options, "allowUnscopedFetchEvents", false);
        if (!isTrue(allowUnscopedFetchEvents))
        {
            this.requireEventQuery(parameters);
        }
        object queries = this.parseSearchQueries(parameters);
        // binance has no tag taxonomy — resolve requested tags through the semantic search too
        object tags = this.safeList(parameters, "tags", new List<object>() {});
        object tagsLength = getArrayLength(tags);
        object allQueries = new List<object>() {};
        for (object i = 0; isLessThan(i, getArrayLength(queries)); postFixIncrement(ref i))
        {
            ((IList<object>)allQueries).Add(getValue(queries, i));
        }
        for (object i = 0; isLessThan(i, tagsLength); postFixIncrement(ref i))
        {
            ((IList<object>)allQueries).Add(getValue(tags, i));
        }
        object allQueriesLength = getArrayLength(allQueries);
        parameters = this.omit(parameters, new List<object>() {"query", "queries"});
        object userLimit = this.safeInteger(parameters, "limit");
        object fetchCap = this.safeInteger(this.options, "maxFetchEventsResults", 100);
        if (isTrue(!isEqual(userLimit, null)))
        {
            fetchCap = userLimit;
        }
        object rest = this.omit(parameters, new List<object>() {"status", "limit", "sort", "searchIn", "eventId", "slug", "tags", "l1Category", "l2Category"});
        object eventId = this.safeString(parameters, "eventId");
        object l1Category = this.safeString(parameters, "l1Category");
        object l2Category = this.safeString(parameters, "l2Category");
        if (!isTrue(this.markets))
        {
            this.markets = this.createSafeDictionary();
        }
        object rawTopics = new List<object>() {};
        if (isTrue(isGreaterThan(allQueriesLength, 0)))
        {
            rawTopics = await this.fetchEventsByQuery(allQueries, fetchCap, rest);
        } else if (isTrue(!isEqual(eventId, null)))
        {
            object detail = await this.fetchRawTopicDetail(eventId, rest);
            rawTopics = new List<object>() {detail};
        } else
        {
            object listingRequest = new Dictionary<string, object>() {};
            if (isTrue(!isEqual(l1Category, null)))
            {
                ((IDictionary<string,object>)listingRequest)["l1Category"] = l1Category;
            }
            if (isTrue(!isEqual(l2Category, null)))
            {
                ((IDictionary<string,object>)listingRequest)["l2Category"] = l2Category;
            }
            object sortBy = this.safeStringUpper2(parameters, "sortBy", "sort");
            if (isTrue(!isEqual(sortBy, null)))
            {
                // map the unified sort values onto the server enum, one of RECOMMENDED,
                // VOLUME, PARTICIPANTS, CREATED_TIME or END_DATE — 'liquidity' has no
                // server-side equivalent and stays in params so the base
                // applyEventFetchParams sorts it client-side instead
                if (isTrue(isEqual(sortBy, "NEWEST")))
                {
                    sortBy = "CREATED_TIME";
                } else if (isTrue(isEqual(sortBy, "LIQUIDITY")))
                {
                    sortBy = null;
                }
                if (isTrue(!isEqual(sortBy, null)))
                {
                    ((IDictionary<string,object>)listingRequest)["sortBy"] = sortBy;
                    parameters = this.omit(parameters, new List<object>() {"sort", "sortBy"});
                }
            }
            object listed = await this.fetchRawTopics(fetchCap, this.extend(listingRequest, rest));
            rawTopics = await this.completeRawTopics(listed);
        }
        object rawTopicsLength = getArrayLength(rawTopics);
        object result = new List<object>() {};
        for (object i = 0; isLessThan(i, rawTopicsLength); postFixIncrement(ref i))
        {
            object parsedEvent = this.parseEvent(getValue(rawTopics, i));
            ((IList<object>)result).Add(parsedEvent);
            object parsedMarkets = (IList<object>)(this.safeList(parsedEvent, "markets", new List<object>() {}));
            object parsedMarketsLength = getArrayLength(parsedMarkets);
            for (object mi = 0; isLessThan(mi, parsedMarketsLength); postFixIncrement(ref mi))
            {
                object m = getValue(parsedMarkets, mi);
                // prediction market rows are keyed by the unified 'market' handle
                object handle = this.safeString(m, "market");
                if (isTrue(!isEqual(handle, null)))
                {
                    ((IDictionary<string,object>)this.markets)[(string)handle] = m;
                }
            }
        }
        this.populateOutcomes();
        // scoping already happened server-side: the tag filter needs an event-level tags field
        // binance topics lack, and the query filter would drop semantic-search matches whose
        // title uses different words than the query
        object postParams = this.omit(parameters, new List<object>() {"tags", "l1Category", "l2Category"});
        return this.applyEventFetchParams(result, postParams, new List<object>() {});
    }

    /**
     * @ignore
     * @method
     * @name binance#fetchEventsByQuery
     * @description resolves free-text queries through the semantic market search endpoint, then completes the matched topics with their outcome tokens
     * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/market-data#market-search
     * @param {string[]} queries free-text search strings
     * @param {int} [limit] max number of topics to fetch
     * @param {object} [rest] extra params forwarded verbatim to the search endpoint
     * @returns {object[]} raw market topic objects with usable nested markets
     */
    public async virtual Task<object> fetchEventsByQuery(object queries, object limit, object rest = null)
    {
        rest ??= new Dictionary<string, object>();
        object seen = new Dictionary<string, object>() {};
        object collected = new List<object>() {};
        object queriesLength = getArrayLength(queries);
        if (isTrue(isEqual(limit, null)))
        {
            limit = 20;
        } else if (isTrue(isGreaterThan(limit, 50)))
        {
            limit = 50;
        }
        for (object qi = 0; isLessThan(qi, queriesLength); postFixIncrement(ref qi))
        {
            object request = new Dictionary<string, object>() {
                { "query", getValue(queries, qi) },
            };
            ((IDictionary<string,object>)request)["topK"] = limit;
            object response = await this.sapiPrivateGetMarketSearch(this.extend(request, rest));
            //
            //     [
            //         {
            //             "marketTopicId": 4229564,
            //             "vendor": "PREDICT_FUN",
            //             "slug": "btc-price-1h-up-or-down",
            //             "title": "BTC Price 1h Up or Down?",
            //             ...
            //             "markets": []
            //         }
            //     ]
            //
            object responseLength = getArrayLength(response);
            for (object i = 0; isLessThan(i, responseLength); postFixIncrement(ref i))
            {
                object rawTopic = getValue(response, i);
                object topicId = this.safeString(rawTopic, "marketTopicId");
                if (isTrue(!isEqual(topicId, null)))
                {
                    object already = this.safeString(seen, topicId);
                    if (isTrue(isEqual(already, null)))
                    {
                        ((IDictionary<string,object>)seen)[(string)topicId] = topicId;
                        ((IList<object>)collected).Add(rawTopic);
                    }
                }
            }
        }
        object capped = collected;
        object collectedLength = getArrayLength(collected);
        if (isTrue(isTrue((!isEqual(limit, null))) && isTrue((isGreaterThan(collectedLength, limit)))))
        {
            capped = this.arraySlice(collected, 0, limit);
        }
        return await this.completeRawTopics(capped);
    }

