        //         "topicType": "FLAT",
        //         "chartType": "CRYPTO_UP_DOWN",
        //         "symbol": "BTCUSDT",
        //         "variantData": { "type": "CRYPTO_UP_DOWN", "startPrice": "67890.12", "endPrice": null },
        //         "participantCount": 3420,
        //         "collateral": "USDT",
        //         "feeRateBps": 200,
        //         "slippageBps": 1200,
        //         "tradeVolume": "158234.56",
        //         "liquidity": "45000.00",
        //         "publishedAt": 1748100000000,
        //         "startDate": 1748131200000,
        //         "endDate": 1748134800000,
        //         "status": "REGISTERED",
        //         "timeline": [ ... ],
        //         "markets": [ { "marketId": 5567895, "title": "UP", "outcomes": [ ... ] } ]
        //     }
        //
        object rawMarkets = (IList<object>)(this.safeList(rawTopic, "markets", new List<object>() {}));
        object marketsList = new List<object>() {};
        object anyActive = false;
        object rawMarketsLength = getArrayLength(rawMarkets);
        for (object i = 0; isLessThan(i, rawMarketsLength); postFixIncrement(ref i))
        {
            object parsed = this.parseTopicMarket(getValue(rawMarkets, i), rawTopic);
            ((IList<object>)marketsList).Add(parsed);
            if (isTrue(this.safeBool(parsed, "active", false)))
            {
                anyActive = true;
            }
        }
        object topicId = this.safeString(rawTopic, "marketTopicId");
        object slug = this.safeString(rawTopic, "slug");
        object title = this.safeString(rawTopic, "title");
        object endDate = this.safeInteger(rawTopic, "endDate");
        object created = this.safeInteger2(rawTopic, "publishedAt", "startDate");
        object status = this.safeString(rawTopic, "status");
        object active = anyActive;
        if (isTrue(isEqual(rawMarketsLength, 0)))
        {
            active = isTrue((isEqual(status, "REGISTERED"))) || isTrue((isEqual(status, "OPEN")));
        }
        object resolved = null;
        if (isTrue(!isEqual(status, null)))
        {
            resolved = isTrue((isEqual(status, "RESOLVED"))) || isTrue((isEqual(status, "SETTLED")));
        }
        return new Dictionary<string, object>() {
            { "id", topicId },
            { "slug", slug },
            { "event", ((bool) isTrue((!isEqual(slug, null)))) ? this.shortenSlug(slug) : null },
            { "title", title },
            { "description", this.safeString(rawTopic, "description") },
            { "markets", marketsList },
            { "active", active },
            { "volume", this.safeNumber(rawTopic, "tradeVolume") },
            { "liquidity", this.safeNumber(rawTopic, "liquidity") },
            { "url", null },
            { "image", this.safeString(rawTopic, "imageUrl") },
            { "created", created },
            { "createdDatetime", this.iso8601(created) },
            { "end", endDate },
            { "endDatetime", this.iso8601(endDate) },
            { "category", this.safeString(rawTopic, "chartType") },
            { "resolved", resolved },
            { "info", rawTopic },
        };
    }

    /**
     * @ignore
     * @method
     * @name binance#parseTopicMarket
     * @description parses one nested market of a market topic into the unified market shape, building its outcome tokens
     * @param {object} rawMarket the nested market object
     * @param {object} rawTopic the enclosing raw market topic (carries slug/vendor/fees/dates)
     * @returns {object} a market structure
     */
    public virtual object parseTopicMarket(object rawMarket, object rawTopic)
    {
        //
        //     {
        //         "marketId": 5567895,
        //         "externalId": "ext_001",
        //         "title": "UP",
        //         "question": "Will BTC go UP?",
        //         "description": "Resolves YES if BTC price increases.",
        //         "conditionId": "0xabc123",
        //         "status": "REGISTERED",
        //         "tradingStatus": "OPEN",
        //         "tradeVolume": "90000.00",
        //         "liquidity": "25000.00",
        //         "decimalPrecision": 2,
        //         "outcomes": [
        //             { "name": "YES", "price": "0.52", "chance": "0.52", "index": 0, "tokenId": "112233" }
        //         ]
        //     }
        //
        object marketId = this.safeString(rawMarket, "marketId");
        object topicId = this.safeString(rawTopic, "marketTopicId");
        object topicSlug = this.safeString(rawTopic, "slug");
        object vendor = this.safeString(rawTopic, "vendor");
        object collateral = this.safeString(rawTopic, "collateral", "USDT");
        object title = this.safeString(rawMarket, "title", marketId);
        object marketSymbol = this.slugToMarketSymbol(topicSlug, title);
        object tradingStatus = this.safeString(rawMarket, "tradingStatus");
        object status = this.safeString(rawMarket, "status");
        object active = (isEqual(tradingStatus, "OPEN"));
        if (isTrue(isEqual(tradingStatus, null)))
        {
            active = isTrue((isEqual(status, "REGISTERED"))) || isTrue((isEqual(status, "OPEN")));
        }
        object resolved = isTrue((isEqual(status, "RESOLVED"))) || isTrue((isEqual(status, "SETTLED")));
        object endDate = this.safeInteger(rawTopic, "endDate");
        object feeRateBps = this.safeString(rawTopic, "feeRateBps", "200");
        object feeRate = this.parseNumber(Precise.stringDiv(feeRateBps, "10000"));
        object decimalPrecision = this.safeString(rawMarket, "decimalPrecision", "2");
        object pricePrecision = this.parseNumber(this.parsePrecision(decimalPrecision));
        object precision = new Dictionary<string, object>() {
            { "amount", 0.01 },
            { "price", pricePrecision },
        };
        object volume = this.safeNumber(rawMarket, "tradeVolume");
        object liquidity = this.safeNumber(rawMarket, "liquidity");
        object rawOutcomes = (IList<object>)(this.safeList(rawMarket, "outcomes", new List<object>() {}));
        object outcomes = new List<object>() {};
        object resolvedOutcomeRaw = null;
        object rawOutcomesLength = getArrayLength(rawOutcomes);
        for (object oi = 0; isLessThan(oi, rawOutcomesLength); postFixIncrement(ref oi))
        {
            object rawOutcome = getValue(rawOutcomes, oi);
            object label = this.safeStringUpper(rawOutcome, "name");
            object tokenId = this.safeString(rawOutcome, "tokenId");
            object outcomeHandle = add(add(marketSymbol, ":"), label);
            object price = this.safeString(rawOutcome, "price");
            object winnerRaw = null;
            object settleFractionRaw = null;
            if (isTrue(isTrue(resolved) && isTrue((!isEqual(price, null)))))
            {
                winnerRaw = Precise.stringEq(price, "1");
                settleFractionRaw = ((bool) isTrue((winnerRaw))) ? 1 : 0;
                if (isTrue(winnerRaw))
                {
                    resolvedOutcomeRaw = outcomeHandle;
                }
            }
            object winner = winnerRaw;
            object settleFraction = settleFractionRaw;
            ((IList<object>)outcomes).Add(new Dictionary<string, object>() {
                { "id", tokenId },
                { "outcomeId", tokenId },
                { "outcome", outcomeHandle },
                { "market", marketSymbol },
                { "label", label },
                { "price", this.parseNumber(price) },
                { "active", active },
                { "winner", winner },
                { "settleFraction", settleFraction },
                { "precision", precision },
                { "info", new Dictionary<string, object>() {
                    { "tokenId", tokenId },
                    { "marketId", marketId },
                    { "marketTopicId", topicId },
                    { "vendor", vendor },
                    { "chainId", this.safeString(rawTopic, "chainId") },
                    { "slug", topicSlug },
                    { "marketTitle", title },
                    { "outcomeLabel", label },
                    { "index", this.safeString(rawOutcome, "index") },
                    { "price", price },
                    { "chance", this.safeString(rawOutcome, "chance") },
                    { "collateral", collateral },
                    { "feeRateBps", feeRateBps },
                    { "slippageBps", this.safeString(rawTopic, "slippageBps") },
                    { "conditionId", this.safeString(rawMarket, "conditionId") },
                    { "externalId", this.safeString(rawMarket, "externalId") },
                } },
            });
        }
        object resolvedOutcome = resolvedOutcomeRaw;
        return new Dictionary<string, object>() {
            { "id", marketId },
            { "market", marketSymbol },
            { "base", collateral },
            { "quote", collateral },
            { "settle", null },
            { "baseId", marketId },
            { "quoteId", collateral },
            { "settleId", null },
            { "type", "prediction" },
            { "marketType", "binary" },
            { "executionModel", "clob" },
            { "collateral", collateral },
            { "spot", false },
            { "margin", false },
            { "swap", false },
            { "future", false },
            { "option", false },
            { "prediction", true },
            { "active", active },
            { "resolved", resolved },
            { "resolvedOutcome", resolvedOutcome },
            { "contract", false },
            { "linear", null },
            { "inverse", null },
            { "contractSize", null },
            { "expiry", endDate },
            { "expiryDatetime", this.iso8601(endDate) },
            { "strike", null },
            { "optionType", null },
            { "taker", feeRate },
            { "maker", 0 },
            { "percentage", true },
            { "tierBased", false },
            { "feeSide", "get" },
            { "precision", precision },
            { "limits", new Dictionary<string, object>() {
                { "leverage", new Dictionary<string, object>() {
                    { "min", 1 },
                    { "max", 1 },
                } },
                { "amount", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "price", new Dictionary<string, object>() {
                    { "min", 0.01 },
                    { "max", 0.99 },
                } },
                { "cost", new Dictionary<string, object>() {
                    { "min", 1.5 },
                    { "max", null },
                } },
            } },
            { "outcomes", outcomes },
            { "info", this.extend(rawMarket, new Dictionary<string, object>() {
                { "marketTopicId", topicId },
                { "vendor", vendor },
                { "slug", topicSlug },
                { "volume", volume },
                { "liquidity", liquidity },
            }) },
            { "created", this.safeInteger(rawTopic, "publishedAt") },
        };
    }

    /**
     * @method
     * @name binance#fetchTicker
     * @description fetches the last trade price for a single prediction outcome
     * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/market-data#query-last-trade-price
     * @param {string} outcome unified outcome handle like BTC_PRICE_1H_UP_DOWN_UP:YES, or an outcome token id
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a prediction [ticker structure](https://docs.ccxt.com/#/?id=ticker-structure)
     */
    public async override Task<object> fetchTicker(object outcome, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadOutcome(outcome);
        object outcomeObj = this.outcome(outcome);
        object info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
        object request = new Dictionary<string, object>() {
            { "marketId", this.safeString(info, "marketId") },
        };
        object response = await this.sapiPrivateGetOrderBookLastTradePrice(this.extend(request, parameters));
        //
        //     { "marketId": 5567895, "lastTradePrice": "0.52" }
        //
        return this.parsePredictionTicker(response, ((object)outcomeObj));
    }

    /**
     * @ignore
     * @method
     * @name binance#parsePredictionTicker
     * @description parses a last-trade-price response into a unified ticker object; the venue quotes the market's primary (YES) token, so a NO outcome mirrors as 1 - price
     * @param {object} raw the raw last-trade-price object
     * @param {object} [market] the outcome object the ticker belongs to
     * @returns {object} a [ticker structure](https://docs.ccxt.com/#/?id=ticker-structure)
     */
    public override object parsePredictionTicker(object raw, object market = null)
    {
        //
        //     { "marketId": 5567895, "lastTradePrice": "0.52" }
        //
        object marketAny = ((object)market);
        object outcomeObj = this.safeOutcome(this.safeString(marketAny, "outcome"), marketAny);
        // the venue quotes the market's primary token (outcome index 0, e.g. YES or UP),
        // any other outcome of a binary market mirrors as 1 - price
        object outcomeInfo = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
        object outcomeIndex = this.safeString(outcomeInfo, "index");
        object isMirrored = false;
        if (isTrue(!isEqual(outcomeIndex, null)))
        {
            isMirrored = (!isEqual(outcomeIndex, "0"));
        } else
        {
            object label = this.safeStringUpper(outcomeObj, "label", "YES");
            isMirrored = isTrue((isEqual(label, "NO"))) || isTrue((isEqual(label, "DOWN")));
        }
        object lastString = this.safeString(raw, "lastTradePrice");
        object last = null;
        if (isTrue(!isEqual(lastString, null)))
        {
            if (isTrue(isMirrored))
            {
                last = this.parseNumber(Precise.stringSub("1", lastString));
            } else
            {
                last = this.parseNumber(lastString);
            }
        }
        object now = this.milliseconds();
        return this.safePredictionTicker(new Dictionary<string, object>() {
            { "outcome", this.safeString(outcomeObj, "outcome") },
            { "outcomeId", this.safeString2(outcomeObj, "outcomeId", "id") },
            { "label", this.safeString(outcomeObj, "label") },
            { "market", this.safeString(outcomeObj, "market") },
            { "timestamp", now },
            { "datetime", this.iso8601(now) },
            { "high", null },
            { "low", null },
            { "bid", null },
            { "bidVolume", null },
            { "ask", null },
            { "askVolume", null },
            { "vwap", null },
            { "open", null },
            { "close", last },
            { "last", last },
            { "previousClose", null },
            { "change", null },
            { "percentage", null },
            { "average", null },
            { "baseVolume", null },
            { "quoteVolume", null },
            { "info", raw },
        }, market);
    }

    /**
     * @method
     * @name binance#fetchTickers
     * @description fetches last trade prices for multiple outcomes, one request per distinct underlying market
     * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/market-data#query-last-trade-price
     * @param {string[]} outcomes unified outcomes — required: the venue has no all-tickers endpoint
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a dictionary of prediction [ticker structures](https://docs.ccxt.com/#/?id=ticker-structure)
     */
    public async override Task<object> fetchTickers(object outcomes = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if (isTrue(isEqual(outcomes, null)))
        {
            throw new ArgumentsRequired ((string)add(this.id, " fetchTickers() requires an outcomes argument — the venue has no all-tickers endpoint; pass the outcome handles to fetch (discover them via fetchEvents ())")) ;
        }
        await this.loadOutcomes(outcomes);
        object responsesByMarketId = new Dictionary<string, object>() {};
        object result = new Dictionary<string, object>() {};
        object outcomesLength = getArrayLength(outcomes);
        for (object i = 0; isLessThan(i, outcomesLength); postFixIncrement(ref i))
        {
            object outcomeObj = this.outcome(getValue(outcomes, i));
            object info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
            object marketId = this.safeString(info, "marketId");
            if (isTrue(isEqual(marketId, null)))
            {
                continue;
            }
            object response = this.safeDict(responsesByMarketId, marketId);
            if (isTrue(isEqual(response, null)))
            {
                object request = new Dictionary<string, object>() {
                    { "marketId", marketId },
                };
                response = await this.sapiPrivateGetOrderBookLastTradePrice(this.extend(request, parameters));
                ((IDictionary<string,object>)responsesByMarketId)[(string)marketId] = response;
            }
            object ticker = this.parsePredictionTicker(response, ((object)outcomeObj));
            object symbolKey = this.safeString(ticker, "outcome", getValue(outcomes, i));
            ((IDictionary<string,object>)result)[(string)symbolKey] = ticker;
        }
        return result;
    }

    /**
     * @method
     * @name binance#fetchOrderBook
     * @description fetches the order book for a single prediction outcome token
     * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/market-data#query-order-book
     * @param {string} outcome unified outcome handle, or an outcome token id
     * @param {int} [limit] not used by binance fetchOrderBook
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a prediction [order book structure](https://docs.ccxt.com/#/?id=order-book-structure)
     */
    public async override Task<object> fetchOrderBook(object outcome, object limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadOutcome(outcome);
        object outcomeObj = this.outcome(outcome);
        object info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
        object request = new Dictionary<string, object>() {
            { "vendor", this.safeString(info, "vendor", this.safeString(this.options, "defaultVendor")) },
            { "marketId", this.safeString(info, "marketId") },
            { "tokenId", this.safeString2(outcomeObj, "outcomeId", "id") },
        };
        object response = await this.sapiPrivateGetOrderBook(this.extend(request, parameters));
        //
        //     {
        //         "outcome": "YES",
        //         "tokenId": "112233",
        //         "timestamp": 1748131800000,
        //         "bids": [ { "price": "0.51", "size": "5000.00" } ],
        //         "asks": [ { "price": "0.52", "size": "3000.00" } ]
        //     }
        //
        object timestamp = this.safeInteger(response, "timestamp");
        object orderbook = this.parseOrderBook(response, this.safeOutcomeSymbol(outcome, outcomeObj), timestamp, "bids", "asks", "price", "size");
        return this.safePredictionOrderBook(orderbook, outcomeObj);
    }

    /**
     * @method
     * @name binance#fetchBalance
     * @description query for balance and get the amount of funds available for trading or funds locked in orders
     * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/wallet#query-payment-option-balances
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.type] 'CeDefi', 'FUNDING', or 'SPOT'
     * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
     */
    public async override Task<object> fetchBalance(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        object type = null;
        var typeparametersVariable = this.handleOptionAndParams(parameters, "fetchBalance", "type", "SPOT");
        type = ((IList<object>)typeparametersVariable)[0];
        parameters = ((IList<object>)typeparametersVariable)[1];
        object response = await this.sapiPrivateGetBalancePaymentOptions(parameters);
        //
        // {
        //     "items": [
        //         {
        //             "accountType": "SPOT",
        //             "availableBalanceDisplay": "1000.00",
        //             "enabled": true
        //         }
        //     ]
        // }
        //
        object result = new Dictionary<string, object>() {
            { "info", response },
        };
        object balances = this.safeList(response, "items", new List<object>() {});
        for (object i = 0; isLessThan(i, getArrayLength(balances)); postFixIncrement(ref i))
        {
            object balance = getValue(balances, i);
            object accountType = this.safeString(balance, "accountType");
            if (isTrue(isEqual(accountType, type)))
            {
                object free = this.safeString(balance, "availableBalanceDisplay");
                object account = this.account();
                ((IDictionary<string,object>)account)["free"] = free;
                ((IDictionary<string,object>)result)["USDT"] = account;
            }
        }
        return this.safeBalance(result);
    }

    /**
     * @ignore
     * @method
     * @name binance#parsePredictionOrder
     * @description parses a raw binance prediction order object into a unified order object
     * @param {object} order the raw order object
     * @param {object} [outcomeObj] the ourtome the order belongs to
     * @returns {object} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public override object parsePredictionOrder(object order, object outcomeObj = null)
    {
        //
        // {
        //     "orderId": "54124",
        //     "vendorOrderId": "0x1234abcd...",
        //     "vendor": "PREDICT_FUN",
        //     "marketTopicId": 4229564,
        //     "slug": "btc-price-1h-up-or-down",
        //     "marketTopicTitle": "BTC Price 1h Up or Down?",
        //     "marketId": 5567895,
        //     "marketTitle": "UP",
        //     "outcome": "YES",
        //     "outcomeIndex": 0,
        //     "status": "OPENING",
        //     "side": "BUY",
        //     "orderType": "LIMIT",
        //     "createTime": 1748131500000,
        //     "modifyTime": 1748131500000,
        //     "makerUsdtAmount": "1.00",
        //     "makerShareQty": "2000.00",
        //     "filledUsdtAmount": "0.00",
        //     "filledShareQty": "0.00",
        //     "fillPercentage": "0.00",
        //     "price": "0.50",
        //     "marketProviderFee": "0.02",
        //     "networkFee": "0.000001"
        // }
        //
        object status = this.parseOrderStatus(this.safeString(order, "status"));
        if (isTrue(isEqual(outcomeObj, null)))
        {
            object marketId = this.safeString(order, "marketId");
            object outcome = this.safeStringUpper(order, "outcome");
            object market = this.safeMarket(marketId);
            object outcomeName = this.safeString(market, "market");
            if (isTrue(isEqual(outcomeName, null)))
            {
                outcomeName = marketId;
            }
            outcomeName = add(outcomeName, add(":", outcome));
            outcomeObj = this.safeOutcome(outcomeName);
        }
        object side = this.safeStringLower(order, "side");
        object timestamp = this.safeInteger(order, "createTime");
        return this.safePredictionOrder(new Dictionary<string, object>() {
            { "id", this.safeString(order, "orderId") },
            { "clientOrderId", null },
            { "info", order },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", null },
            { "status", status },
            { "outcome", this.safeString(outcomeObj, "outcome") },
            { "outcomeId", this.safeString(outcomeObj, "id") },
            { "label", this.safeString(outcomeObj, "label") },
            { "market", this.safeString(outcomeObj, "market") },
            { "type", this.safeStringLower(order, "orderType") },
            { "timeInForce", null },
            { "postOnly", null },
            { "reduceOnly", null },
            { "side", side },
            { "price", this.safeNumber(order, "price") },
            { "triggerPrice", null },
            { "amount", null },
            { "cost", null },
            { "average", null },
            { "filled", null },
            { "remaining", null },
            { "fee", null },
            { "trades", new List<object>() {} },
        }, outcomeObj);
    }

    public virtual object parseOrderStatus(object status)
    {
        object statuses = new Dictionary<string, object>() {
            { "OPENING", "open" },
            { "FILLED", "closed" },
        };
        if (isTrue(isEqual(status, null)))
        {
            return null;
        }
        if (isTrue(((string)status).EndsWith(((string)"Rejected"))))
        {
            return "rejected";
        }
        if (isTrue(((string)status).EndsWith(((string)"Canceled"))))
        {
            return "canceled";
        }
        return this.safeString(statuses, status, status);
    }

    /**
     * @method
     * @name binance#fetchOpenOrders
     * @description fetches currently open orders for the user
     * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/trade#query-active-orders
     * @param {string} [outcome] filter by outcome
     * @param {int} [since] only return orders updated since this timestamp in ms
     * @param {int} [limit] max number of orders to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.tradeSide] Filter by trade side. Enum: BUY, SELL
     * @param {string} [params.l1Category] Filter by level-1 category
     * @param {boolean} [params.paginate] *spot only* default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @returns {object[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public async override Task<object> fetchOpenOrders(object outcome = null, object since = null, object limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        object paginate = false;
