    /**
     * @method
     * @name binance#fetchPositions
     * @description fetches the user's outcome positions; outcome positions are spot token balances under the "+<encoding>" coin form (size and entry notional), the value/entry/mark price/pnl are computed from the current mid prices
     * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/position#query-positions
     * @param {string[]} [outcomes] filter by outcome ids or outcomes
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.tab] Position status tab. Values from PositionQueryType. Default ONGOING
     * @returns {object[]} a list of [prediction position structures](https://docs.ccxt.com/#/?id=prediction-position-structure)
     */
    public async override Task<object> fetchPositions(object outcomes = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadOutcomes();
        object requestedOutcomeSymbols = new Dictionary<string, object>() {};
        if (isTrue(!isEqual(outcomes, null)))
        {
            for (object i = 0; isLessThan(i, getArrayLength(outcomes)); postFixIncrement(ref i))
            {
                object requested = getValue(outcomes, i);
                object requestedOutcomeObj = this.safeOutcome(requested);
                object requestedOutcome = this.safeString(requestedOutcomeObj, "outcome", requested);
                ((IDictionary<string,object>)requestedOutcomeSymbols)[(string)requestedOutcome] = true;
            }
        }
        object wallet = await this.fetchWallet("fetchPositions", parameters);
        object request = new Dictionary<string, object>() {
            { "walletAddress", getValue(wallet, "walletAddress") },
        };
        object response = await this.sapiPrivateGetPositionList(this.extend(request, parameters));
        //
        // {
        //     "summary": {
        //         "totalValue": "1523.45",
        //         "positionValue": "523.45",
        //         "walletBalance": "1000.00",
        //         "totalClaimableAmount": "50.00",
        //         "todayRealizedPnl": "15.30",
        //         "todayRealizedPnlPercent": "3.10",
        //         "todayTotalCost": "493.55"
        //     },
        //     "counts": {
        //         "ongoingCount": 3,
        //         "endedCount": 12,
        //         "pendingClaimCount": 1
        //     },
        //     "positions": [
        //         {
        //             "positionId": 1001,
        //             "vendor": "PREDICT_FUN",
        //             "chainId": "56",
        //             "tokenId": "112233",
        //             "collateralSymbol": "USDT",
        //             "topicType": "FLAT",
        //             "marketTopicId": 4229564,
        //             "marketId": 5567895,
        //             "marketTopicTitle": "BTC Price 1h Up or Down?",
        //             "marketTitle": "UP",
        //             "outcomeName": "YES",
        //             "outcomeIndex": 0,
        //             "shares": "1923.07",
        //             "avgPrice": "0.52",
        //             "totalCost": "1.00",
        //             "value": "1.06",
        //             "currentPrice": "0.55",
        //             "toWin": "1923.07",
        //             "positionStatus": "OPEN",
        //             "canClaim": false,
        //             "endDate": 1748134800000,
        //             "unrealizedPnl": "0.06",
        //             "unrealizedPnlPercent": "6.00",
        //             "realizedPnl": "0.00",
        //             "pnl": "0.06",
        //             "createdTime": 1748131500000,
        //             "updatedTime": 1748132000000
        //         }
        //     ]
        // }
        //
        object data = this.safeList(response, "positions", new List<object>() {});
        object positions = this.parsePredictionPositions(data);
        if (isTrue(isEqual(outcomes, null)))
        {
            return positions;
        }
        object filtered = new List<object>() {};
        object positionsLength = getArrayLength(positions);
        for (object i = 0; isLessThan(i, positionsLength); postFixIncrement(ref i))
        {
            object position = getValue(positions, i);
            object positionOutcome = this.safeString(position, "outcome");
            if (isTrue(isTrue((!isEqual(positionOutcome, null))) && isTrue((inOp(requestedOutcomeSymbols, positionOutcome)))))
            {
                ((IList<object>)filtered).Add(position);
            }
        }
        return filtered;
    }

